478	// Store is a persistent workbench backed by one local data directory.
479	//
480	// All operations are safe for concurrent use by multiple goroutines and by
481	// several processes pointed at the same directory: an in-process mutex plus a
482	// process-shared flock serialize commits, and every commit is an atomic
483	// temp-file/fsync/rename replacement. Open the directory with Open and call
484	// Close when done.
485	type Store struct {
486		dir  string
487		mu   sync.Mutex
488		lock *os.File
489	
490		data envelope
491	}
492	
493	// Open opens (creating if needed) the workbench data in dir. If the
494	// directory does not exist it is created. Existing committed data is loaded
495	// and fully validated before Open returns; on a corrupt, truncated or
496	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
497	// leaves every file in the directory untouched.
498	func Open(dir string) (*Store, error) {
499		if dir == "" {
500			return nil, invalidf("data directory must not be empty")
501		}
502		if err := os.MkdirAll(dir, 0o755); err != nil {
503			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
504		}
505		lockPath := filepath.Join(dir, dirLockFile)
506		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
507		if err != nil {
508			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
509		}
510		// Serialize against other processes while we read / validate.
511		if err := lockExclusive(lock); err != nil {
512			lock.Close()
513			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
514		}
515	
516		s := &Store{dir: dir, lock: lock}
517		if err := s.loadLocked(); err != nil {
518			unlockLock(lock)
519			lock.Close()
520			return nil, err
521		}
522		// The lock is taken again per operation; holding it for the store's
523		// lifetime would forbid two open handles on one directory.
524		if err := unlockLock(lock); err != nil {
525			lock.Close()
526			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
527		}
528		return s, nil
529	}
530	
531	// Close releases the directory lock. It does not discard committed data.
532	func (s *Store) Close() error {
533		s.mu.Lock()
534		defer s.mu.Unlock()
535		if s.lock == nil {
536			return nil
537		}
538		var first error
539		if err := unlockLock(s.lock); err != nil {
540			first = err
541		}
542		if err := s.lock.Close(); err != nil && first == nil {
543			first = err
544		}
545		s.lock = nil
546		return first
547	}
548	
549	// Dir reports the data directory backing the store.
550	func (s *Store) Dir() string { return s.dir }
551	
552	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
553	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
554	
555	// loadLocked reads and validates the committed file. Caller must hold the
556	// exclusive flock; the in-process mutex is taken by the public Open path.
557	func (s *Store) loadLocked() error {
558		raw, err := os.ReadFile(s.dataPath())
559		if errors.Is(err, os.ErrNotExist) {
560			s.data = envelope{Format: FormatVersion}
561			return nil
562		}
563		if err != nil {
564			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
565		}
566		if len(strings.TrimSpace(string(raw))) == 0 {
567			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
568		}
569	
570		var env envelope
571		if err := json.Unmarshal(raw, &env); err != nil {
572			// Shape failures surfaced by the persisted-definition decoders are
573			// integrity failures, not JSON syntax errors; report their detail
574			// instead of the generic "not valid JSON" wording.
575			var se StoreError
576			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
577				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
578			}
579			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
580		}
581		if env.Format == 0 {
582			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
583		}
584		if env.Format != FormatVersion {
585			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
586				s.dataPath(), env.Format, FormatVersion)
587		}
588		if err := validateEnvelope(env); err != nil {
589			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
590		}
591		s.data = env
592		return nil
593	}
594	
595	// commitLocked writes the pending state atomically: temp file → fsync →
596	// rename → fsync directory. Caller must hold both the in-process mutex and
597	// the exclusive flock; all in-memory mutations must already have happened and
598	// been rule-checked, so a failure here occurs before any success is reported.
599	func (s *Store) commitLocked() error {
600		s.data.Format = FormatVersion
601		// Stable output: records are stored sorted so files are deterministic.
602		sortEnvelope(&s.data)
603	
604		payload, err := json.MarshalIndent(&s.data, "", "  ")
605		if err != nil {
606			return fmt.Errorf("cannot encode data: %w", err)
607		}
608		payload = append(payload, '\n')
609	
610		tmp := s.tmpPath()
611		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
612		if err != nil {
613			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
614		}
615		if _, err := f.Write(payload); err != nil {
616			f.Close()
617			os.Remove(tmp)
618			return fmt.Errorf("cannot write staged data: %w", err)
619		}
620		if err := f.Sync(); err != nil {
621			f.Close()
622			os.Remove(tmp)
623			return fmt.Errorf("cannot flush staged data: %w", err)
624		}
625		if err := f.Close(); err != nil {
626			os.Remove(tmp)
627			return fmt.Errorf("cannot finish staged data: %w", err)
628		}
629		if err := os.Rename(tmp, s.dataPath()); err != nil {
630			os.Remove(tmp)
631			return fmt.Errorf("cannot commit data file: %w", err)
632		}
633		if err := syncDir(s.dir); err != nil {
634			// The rename already happened; lack of dir fsync only weakens crash
635			// durability, never correctness of what is visible now.
636			return nil
637		}
638		return nil
639	}
640	
641	// withLock runs fn under the in-process mutex and an exclusive flock, then
642	// atomically commits when fn requests it. The on-disk state is re-read after
643	// acquiring the lock, so concurrent commits from another process or another
644	// handle are always observed. Operations validate before mutating; a rejected
645	// operation (commit=false or an error) writes nothing and leaves committed
646	// state unchanged.
647	func (s *Store) withLock(fn func() (commit bool, err error)) error {
648		s.mu.Lock()
649		defer s.mu.Unlock()
650		if s.lock == nil {
651			return invalidf("store is closed")
652		}
653		if err := lockExclusive(s.lock); err != nil {
654			return fmt.Errorf("cannot lock data directory: %w", err)
655		}
656		defer unlockLock(s.lock)
657	
658		if err := s.loadLocked(); err != nil {
659			return err
660		}
661		commit, err := fn()
662		if err != nil {
663			return err
664		}
665		if !commit {
666			return nil
667		}
668		return s.commitLocked()
669	}
670	
671	// withLockRead runs fn under a shared flock over freshly reloaded state.
672	func (s *Store) withLockRead(fn func() error) error {
673		s.mu.Lock()
674		defer s.mu.Unlock()
675		if s.lock == nil {
676			return invalidf("store is closed")
677		}
678		if err := lockShared(s.lock); err != nil {
679			return fmt.Errorf("cannot lock data directory: %w", err)
680		}
681		defer unlockLock(s.lock)
682		if err := s.loadLocked(); err != nil {
683			return err
684		}
685		return fn()
686	}
687	
688	func sortEnvelope(env *envelope) {
689		sort.Slice(env.Circuits, func(i, j int) bool {
690			if env.Circuits[i].Name != env.Circuits[j].Name {
691				return env.Circuits[i].Name < env.Circuits[j].Name
692			}
693			return env.Circuits[i].Version < env.Circuits[j].Version
694		})
695		sort.Slice(env.Setups, func(i, j int) bool {
696			if env.Setups[i].Name != env.Setups[j].Name {
697				return env.Setups[i].Name < env.Setups[j].Name
698			}
699			return env.Setups[i].Version < env.Setups[j].Version
700		})
701		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
702		sort.Slice(env.Artifacts, func(i, j int) bool {
703			if env.Artifacts[i].Name != env.Artifacts[j].Name {
704				return env.Artifacts[i].Name < env.Artifacts[j].Name
705			}
706			return env.Artifacts[i].Version < env.Artifacts[j].Version
707		})
708	}
709	
710	// validateEnvelope re-checks every invariant on load so a tampered or
711	// hand-edited file cannot bypass the domain rules.
712	func validateEnvelope(env envelope) error {
713		seenCircuit := make(map[[2]string]bool)
714		circuitOK := make(map[[2]string]bool)
715		for i, c := range env.Circuits {
716			key := [2]string{c.Name, itoa(c.Version)}
717			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
718				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
719			}
720			if c.Version <= 0 {
721				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
722			}
723			if seenCircuit[key] {
724				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
725			}
726			seenCircuit[key] = true
727			if c.Constraints <= 0 {
728				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
729			}
730			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
731				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
732			}
733			if c.Definition != nil {
734				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
735					return err
736				}
737			}
738			circuitOK[key] = true
739		}
740		seenSetup := make(map[[2]string]bool)
741		for i, p := range env.Setups {
742			key := [2]string{p.Name, itoa(p.Version)}
743			if !circuitOK[key] {
744				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
745			}
746			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
747			if c == nil || !c.Frozen {
748				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
749			}
750			if seenSetup[key] {
751				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
752			}
753			seenSetup[key] = true
754		}
755		seenJob := make(map[string]bool)
756		for i, j := range env.Jobs {
757			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
758				return fmt.Errorf("job #%d has an empty or blank id", i+1)
759			}
760			if seenJob[j.ID] {
761				return fmt.Errorf("job %q appears more than once", j.ID)
762			}
763			seenJob[j.ID] = true
764			if j.Kind != "prove" {
765				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
766			}
767			if j.Attempt <= 0 {
768				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
769			}
770			key := [2]string{j.Circuit, itoa(j.Version)}
771			if !circuitOK[key] {
772				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
773			}
774			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
775			if c == nil || !c.Frozen {
776				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
777			}
778			if !seenSetup[key] {
779				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
780			}
781			// A recorded compiled-artifact binding must still resolve against the
782			// pinned version's artifact; a dangling or mismatched binding makes
783			// the file unreadable rather than silently dropping the binding.
784			if j.CompiledHash != "" {
785				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
786				if artifact == nil {
787					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
788				}
789				if artifact.Hash != j.CompiledHash {
790					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
791						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
792				}
793			}
794		}
795		seenArtifact := make(map[[2]string]bool)
796		for i, a := range env.Artifacts {
797			key := [2]string{a.Name, itoa(a.Version)}
798			if !circuitOK[key] {
799				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
800			}
801			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
802			if c == nil || !c.Frozen {
803				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
804			}
805			if seenArtifact[key] {
806				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
807			}
808			seenArtifact[key] = true
809			if c.Definition == nil {
810				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
811			}
812			if a.Constraints != c.Constraints {
813				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
814					a.Name, a.Version, a.Constraints, c.Constraints)
815			}
816			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
817			if err != nil {
818				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
819			}
820			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
821				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
822			}
823			wantHash := artifactHash(a.Name, a.Version, def)
824			if a.Hash != wantHash {
825				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
826					a.Name, a.Version, a.Hash, wantHash)
827			}
828		}
829		return nil
830	}
831	
832	// validatePersistDefinition re-validates a stored definition against its
833	// version's declared counts: prime modulus, in-range wires and an exact
834	// constraint count match.
835	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
836		parsed, err := definitionFromPersist(*def, public, private)
837		if err != nil {
838			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
839		}
840		if !parsed.compatibleWith(constraints, public, private) {
841			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
842		}
843		return nil
844	}
845	
846	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
847		for i := range cs {
848			if cs[i].Name == name && cs[i].Version == version {
849				return &cs[i]
850			}
851		}
852		return nil
853	}
854	
855	func itoa(v int) string { return fmt.Sprintf("%d", v) }
856

