// jobObjectMembers decodes one committed job record into its raw members,
// rejecting repeated keys (encoding/json would silently keep the last value,
// letting a second compiled_hash override the first). Keys are compared after
// JSON unescaping, matching the envelope scanner.
func jobObjectMembers(raw []byte, what string) (map[string]json.RawMessage, error) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || trimmed[0] != '{' {
		return nil, corruptf("%s must be a JSON object", what)
	}
	dec := json.NewDecoder(bytes.NewReader(trimmed))
	dec.UseNumber()
	open, err := dec.Token()
	if err != nil || open != json.Delim('{') {
		return nil, corruptf("%s must be a JSON object", what)
	}
	members := make(map[string]json.RawMessage)
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, corruptf("%s is not valid JSON: %v", what, err)
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil, corruptf("%s is not valid JSON", what)
		}
		if _, repeated := members[key]; repeated {
			return nil, corruptf("%s contains duplicate field %q", what, key)
		}
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return nil, corruptf("%s is not valid JSON: %v", what, err)
		}
		members[key] = value
	}
	if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
		return nil, corruptf("%s is not valid JSON", what)
	}
	if _, err := dec.Token(); err != io.EOF {
		return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
	}
	return members, nil
}
